	for(let i=(frameCount/500)%(1/sliceCount) ;i<1;i+=(Math.max(0.001, Math.abs(1/sliceCount)) || 1)){
		const ratio = i % 1
		// fill(i*255)
		// fill(lerpColor(colorFrom,colorTo,i))
		stroke(lerpColor(colorFrom,colorTo,i))
		strokeWeight(2)
		noFill()
		sphereEllipse(x, y, w, h, ratio)
	}
}

