// === Tab: mySketch ===
const circleArr = []
const delaunay = new c2.Delaunay();

const palette = ["#d4aa7d","#efd09e","#d2d8b3","#90a9b7"]
const floorColor = "#F8F5F0"

async function setup() {
	const canvaSize = max(windowWidth, windowHeight)
	createCanvas(canvaSize, canvaSize);
	angleMode(DEGREES)
	background("#272727")


	for(let i=0;i<1000;i++){
		const averageRBase = 150
		for(let j=0;j<20;j++){
			const averageR = map(j,0,19,averageRBase,40)
			let r = randomGaussian(averageR, averageR/4)
			let _wG_1 = 0; while ((r<30) && ++_wG_1 < 20000){
				r = randomGaussian(averageR, averageR/4)
			}
			const x = random(r, width-r)
			const y = random(r+30, height*2-r*2)
			let valid = true
			for(let c of circleArr){
				const distC = dist(x, y, c.x, c.y)
				if(distC<c.r+r+5){
					valid = false
					break;
				}
			}
			if(valid){
				const c = new c2.Point(x, y)
				c.r = r
				c.colorFrom = random(palette)
				c.colorTo = random(palette)
				circleArr.push(c)
				break;
			}
		}
	}

	circleArr.sort((a, b) => a.y - b.y)

	for(let c of circleArr){
		noStroke()
		fill("#E9DECB")
		ellipse(c.x, c.y/2, c.r*2, c.r)
		arc(c.x, c.y/2, c.r*2, c.r*2, 0, 180)

		strokeWeight(random(1.2,1.5))
		// stroke(0,50)
		noFill()

		const pointCount = map(pow(c.r,2),0,10000,50,10000)
		for(let i=0;i<pointCount;i++){
			const theta1 = random(360)
			const theta2 = -asin(random())
			pointColor = lerpColor(color(c.colorFrom), color(c.colorTo), abs(theta2)/90)
			if(random()<0.7){
				stroke(pointColor)
			}else{
				stroke(0,50)
			}
			sphereDot(c.x, c.y/2, c.r*2, c.r, theta1, theta2)
		}

		noStroke()
		fill(floorColor)
		ellipse(c.x, c.y/2, c.r*2, c.r)

		await sleep(10)
	}

	delaunay.compute(circleArr)
	// print(delaunay)

	for(let edge of delaunay.edges){
		stroke(floorColor)
		// stroke(0)
		strokeWeight(5)
		if(
			edge.p1.x<60 || edge.p1.x>width-60 ||
			edge.p1.y/2<60 || edge.p1.y/2>height-60 ||
			(edge.length - edge.p1.r - edge.p2.r > max(width, height)/4)
		){
			continue
		}
		line(edge.p1.x, edge.p1.y/2, edge.p2.x, edge.p2.y/2)
		await sleep(10)
	}

	blendMode(MULTIPLY)

	for(let i=0;i<20000;i++){
		strokeWeight(random(1.2 ))
		const x = random(width)
		const y = random(height)
		stroke(random(palette))
		point(x,y)
	}
}

